/* patents/model.ts: the shape of app/public/data/patents.json and the three
 * lookups the page needs.
 *
 * The file is generated by tools/build_app_data.py out of research/patents-view.json
 * and research/observables-view.json, which are the authored surfaces. Nothing here
 * writes a fact: every string the page draws comes out of these types.
 *
 * `inventor` and `assignee` are null on every record because no structured field on
 * this board carries them, so they are typed as null and never filled in. The
 * assignment is stated in `standfirst` and in each record's own `sub` line.
 */

const BASE = import.meta.env.BASE_URL;

export interface Sheet {
  k: number;
  file: string;
  thumb: string;
  caption: string;
  fig: number;
  patent: string;
}

export interface ProsecutionStep {
  date: string;
  kind: string;
  label: string;
  file: string | null;
  note?: string | null;
}

export interface Fee { finding?: string; lapsed?: string; title?: string }
export interface AbsentPaper { label: string; why: string }
export interface Cite { name: string; url?: string | null }

export interface Patent {
  number: string;
  node: string | null;
  title: string;
  status: string[];
  granted: string | null;
  filed: string | null;
  published: string | null;
  expired: string | null;
  application: string | null;
  docket: string | null;
  examiner: string | null;
  supervisor: string | null;
  artUnits: string[] | null;
  sub: string | null;
  fee: Fee | null;
  inventor: null;
  assignee: null;
  sheets: Sheet[];
  prosecution: ProsecutionStep[];
  absent?: AbsentPaper[];
  source?: Cite | null;
}

export interface Wording { text: string; where: string }
export interface Observable {
  id: string;
  label: string;
  note?: string;
  unsettled?: boolean;
  wordings: Wording[];
}

export interface ObservablesView {
  title: string;
  tier: number;
  node: string | null;
  attribution: string;
  caveat: string;
  observables: Observable[];
  sources?: Cite[];
}

export interface Drawings {
  provenance: string;
  standfirst: string;
  treatment: string;
  unmatchedSheets: Sheet[];
}

export interface Quote {
  date: string;
  speaker: string;
  text: string;
  emphasis?: string;
  gloss?: string;
  tier: number;
  source: Cite;
}

export interface Finding {
  id: string;
  title: string;
  text: string;
  coda?: string;
  tier: number;
  rows: { date: string; number: string }[];
  source?: Cite;
}

export interface PatentsFile {
  title: string;
  eyebrow: string;
  standfirst: string;
  generated: string;
  source: string;
  patents: Patent[];
  drawings: Drawings;
  observables: ObservablesView;
  quotes: Quote[];
  findings: Finding[];
}

let pending: Promise<PatentsFile> | null = null;
export function loadPatents(): Promise<PatentsFile> {
  if (!pending) {
    pending = fetch(BASE + 'data/patents.json').then((r) => {
      if (!r.ok) throw new Error('patents.json -> HTTP ' + r.status);
      return r.json() as Promise<PatentsFile>;
    });
  }
  return pending;
}

/* The route carries digits only: `US 10,144,532` is #/patents/10144532 and
   `US 2019/0058105` is #/patents/20190058105. The key is derived from the
   record's own number, never typed. */
export function patentKey(number: string): string {
  return number.replace(/[^0-9]/g, '');
}

export function findPatent(file: PatentsFile, key: string): Patent | undefined {
  const want = key.replace(/[^0-9]/g, '');
  return file.patents.find((p) => patentKey(p.number) === want);
}

/* Every sheet on the board in the order the data gives it, the unmatched one
   included: `k` is the data's own index and it is what ?sheet= carries. */
export function allSheets(file: PatentsFile): Sheet[] {
  const out: Sheet[] = [];
  for (const p of file.patents) out.push(...p.sheets);
  out.push(...file.drawings.unmatchedSheets);
  return out.sort((a, b) => a.k - b.k);
}

export function matchedSheets(file: PatentsFile): Sheet[] {
  const out: Sheet[] = [];
  for (const p of file.patents) out.push(...p.sheets);
  return out.sort((a, b) => a.k - b.k);
}

/* A quote concerns a patent when the paper it cites is that patent's own
   application. The application number is in the record; the match is on it and
   on the patent number, and on nothing looser. */
export function quotesFor(file: PatentsFile, p: Patent): Quote[] {
  const keys = [p.application, p.number].filter(Boolean) as string[];
  return file.quotes.filter((q) => {
    const name = (q.source && q.source.name) || '';
    return keys.some((k) => name.indexOf(k) >= 0);
  });
}

/* A finding concerns a patent when one of its own rows names that patent. */
export function findingsFor(file: PatentsFile, p: Patent): Finding[] {
  return file.findings.filter((f) => (f.rows || []).some((r) => r.number === p.number));
}

export function sheetSrc(file: string): string { return BASE + 'patents/' + file; }
export function thumbSrc(thumb: string): string { return BASE + 'patents/' + thumb; }

/* Dates print exactly as the record holds them. Nothing is reformatted into a
   month name that the source does not use. */
export function dateOr(v: string | null | undefined, absent: string): string {
  return v ? v : absent;
}
